import sqlglot

# Test cases
test_cases = [
    # Original issue case
    {
        "name": "Original issue - qualified masking policy",
        "query": """
        create or replace view DB.SCHEMA.USERS_VW(
         ID,
         FIRST_NAME MASKING POLICY DB.SCHEMA.PII
        ) as
        select  $1::int as id, 
                $2::varchar as first_name
        from @datalake/users.csv
        ( FILE_FORMAT => 'csv_for_doublequote')
        ;
        """,
        "should_work": True
    },

    # Simple masking policy (unqualified)
    {
        "name": "Simple masking policy",
        "query": """
        CREATE VIEW v (id MASKING POLICY simple_policy) AS SELECT 1
        """,
        "should_work": True
    },

    # Multiple columns with masking policies
    {
        "name": "Multiple columns with masking policies",
        "query": """
        CREATE VIEW v (
            id,
            first_name MASKING POLICY db.schema.fname_policy,
            last_name MASKING POLICY lname_policy
        ) AS SELECT 1, 'John', 'Doe'
        """,
        "should_work": True
    },

    # With USING clause
    {
        "name": "Masking policy with USING clause",
        "query": """
        CREATE TABLE t (
            id INT MASKING POLICY p USING (col1, col2)
        )
        """,
        "should_work": True
    },

    # Projection policy (should also work now)
    {
        "name": "Projection policy with qualified name",
        "query": """
        CREATE VIEW v (
            id PROJECTION POLICY proj.db.policy_name
        ) AS SELECT 1
        """,
        "should_work": True
    }
]

