        result = sqlglot.parse(test_case['query'], sqlglot.Dialects.SNOWFLAKE)
        if test_case['should_work']:
            print("  ✓ PASSED - Parsed successfully")
        else:
            print("  ✗ FAILED - Should have failed but didn't")
            all_passed = False
    except Exception as e:
        if test_case['should_work']:
            print(f"  ✗ FAILED - Should have worked: {e}")
            all_passed = False
        else:
            print("  ✓ PASSED - Correctly failed to parse")

    print()

if all_passed:
    print("🎉 All tests passed!")
else:
    print("❌ Some tests failed")

