#!/usr/bin/env python3
"""
Reproduction script for the inspect.getfullargspec vs inspect.signature issue.
"""

from functools import wraps
import inspect
import tempfile
import shutil
from joblib import Memory

def test_inspect_functions():
    """Demonstrate the difference between inspect.signature and inspect.getfullargspec"""
    print("=== Testing inspect functions ===")

    def decorate(f):
        @wraps(f)
        def wrapped(*args, **kwargs):
            return f(*args, **kwargs)
        return wrapped

    @decorate
    def foo(arg, extra=None):
        return arg

    print("inspect.signature(foo):", inspect.signature(foo))
    try:
        print("inspect.getfullargspec(foo):", inspect.getfullargspec(foo))
    except Exception as e:
        print("inspect.getfullargspec(foo) failed:", e)

def test_memory_cache_issue():
    """Reproduce the actual issue with Memory.cache and decorators"""
    print("\n=== Testing Memory.cache issue ===")

    # Create temporary directory for cache
    tmp_dir = tempfile.mkdtemp()
    mem = Memory(tmp_dir, verbose=0)

    def decorate(f):
        @wraps(f)
        def wrapped(*args, **kwargs):
            return f(*args, **kwargs)
        return wrapped

    @mem.cache(ignore=["extra"])
    @decorate
