    mem = Memory(tmp_dir, verbose=0)

    def decorate1(f):
        @wraps(f)
        def wrapped(*args, **kwargs):
            return f(*args, **kwargs)
        return wrapped

    def decorate2(f):
        @wraps(f)
        def wrapped(*args, **kwargs):
            return f(*args, **kwargs)
        return wrapped

    @mem.cache(ignore=["extra"])
    @decorate1
    @decorate2
    def foo(arg, extra=None):
        return arg

    try:
        result = foo(42)
        print("SUCCESS: Multiple decorators work, foo(42) =", result)
    except Exception as e:
        print("ERROR:", str(e))
