    def decorate(f):
        @wraps(f)
        def wrapped(*args, **kwargs):
            return f(*args, **kwargs)
        return wrapped

    @mem.cache(ignore=["kw2"])
    @decorate
    def func_with_kwonly_args(a, b, *, kw1='kw1', kw2='kw2'):
        return a, b, kw1, kw2

    try:
        result = func_with_kwonly_args(1, 2, kw1=3, kw2='ignored')
        print("SUCCESS: Keyword-only args work, result =", result)
        # Second call should use cache
        result2 = func_with_kwonly_args(1, 2, kw1=3, kw2='different')
