"""
Test edge cases for template support in dictionaries
"""

from vault_cli.testing import TestVaultClient


def test_nested_dicts():
    """Test deeply nested dictionaries with templates"""
    print("=== Testing nested dictionaries ===")

    vault = TestVaultClient()

    vault.db = {
        "secret1": {"value": "value1"},
        "secret2": {"value": "value2"},
        "nested_config": {
            "value": {
                "level1": {
                    "level2": {
                        "templated_value": "!template!{{ vault('secret1') }}",
                        "regular_value": "plain_text"
                    },
                    "another_templated": "!template!{{ vault('secret2') }}"
                },
                "top_level": "also_plain"
            }
        }
    }

    result = vault.get_secret("nested_config")
    expected = {
        "level1": {
            "level2": {
                "templated_value": "value1",
                "regular_value": "plain_text"
            },
            "another_templated": "value2"
        },
        "top_level": "also_plain"
    }

    print("Result:", result)
    print("Expected:", expected)
    print("Match?", result == expected)
    return result == expected


def test_lists_with_templates():
    """Test lists containing templates"""
    print("\n=== Testing lists with templates ===")

    vault = TestVaultClient()

    vault.db = {
        "item1": {"value": "first"},
        "item2": {"value": "second"},
        "list_config": {
            "value": [
                "!template!{{ vault('item1') }}",
                "plain_item",
                "!template!{{ vault('item2') }}",
                {"nested": "!template!{{ vault('item1') }}_suffix"}
            ]
        }
    }

    result = vault.get_secret("list_config")
    expected = [
        "first",
        "plain_item", 
        "second",
        {"nested": "first_suffix"}
    ]

    print("Result:", result)
    print("Expected:", expected)
    print("Match?", result == expected)
    return result == expected


def test_mixed_types():
    """Test mixed data types"""
    print("\n=== Testing mixed data types ===")

    vault = TestVaultClient()

    vault.db = {
        "secret_val": {"value": "templated_value"},
        "mixed_config": {
            "value": {
                "string_template": "!template!{{ vault('secret_val') }}",
                "plain_string": "just_text",
                "integer": 42,
