def test_direct_get_records_call():
    """Try calling get_records directly with manipulated inputs."""
    print("Testing direct get_records call with potential tuple issue...")

    # Create a FormattedTB instance
    tb_handler = FormattedTB(color_scheme='NoColor')

    # Create the exact scenario from the bug report
    try:
        try:
            5 / 0
        except Exception as e:
            raise SystemExit
    except SystemExit as se:
        # Get the traceback
        exc_type, exc_value, exc_tb = sys.exc_info()
        print(f"Exception: {exc_type}")
        print(f"Traceback type: {type(exc_tb)}")

        # Examine the traceback chain
        tb = exc_tb
        while tb:
            print(f"  tb type: {type(tb)}, has tb_frame: {hasattr(tb, 'tb_frame')}")
            if hasattr(tb, 'tb_frame'):
                print(f"    tb_frame type: {type(tb.tb_frame)}")
            if hasattr(tb, 'tb_next'):
                print(f"    tb_next type: {type(tb.tb_next)}")
            tb = tb.tb_next

        # Try to call get_records directly
        try:
            print("\nCalling get_records...")
            records = tb_handler.get_records(exc_tb, 5, 0)
            print(f"Successfully got {len(records)} records")
