                self.tb_frame = tb_frame
                # Intentionally make tb_next a tuple to simulate the bug
                self.tb_next = tb_next if tb_next is not None else ("fake", "tuple")

        # This should cause issues when the code tries to access tb_next.tb_frame
        fake_tb = FakeTB(exc_tb.tb_frame, ("this", "is", "a", "tuple"))

