    for lb in loadbalancers:
        for pool in lb.pools:
            pool_members.extend(pool.members)

    # Get router custom routes for each network
    network_custom_routes = {}
    if hasattr(self._network_driver, 'get_router_custom_routes'):
        for network_id in network_ids:
            custom_routes = self._network_driver.get_router_custom_routes(network_id)
            if custom_routes:
                network_custom_routes[network_id] = custom_routes

