def _etuplize_generator(x, shallow=False, return_bad_args=False, convert_ConsPairs=True):
    """Generator that yields etuplize steps for trampolining."""
    if isinstance(x, ExpressionTuple):
        yield x
        return
    elif convert_ConsPairs and x is not None and isinstance(x, (ConsNull, ConsPair)):
        yield etuple(*x)
        return

    try:
        op, args = rator(x), rands(x)
    except ConsError:
        op, args = None, None

    if not callable(op) or not isinstance(args, (ConsNull, ConsPair)):
        if return_bad_args:
            yield x
            return
        else:
            raise TypeError(f"x is neither a non-str Sequence nor term: {type(x)}")

    if shallow:
        et_op = op
        et_args = args
    else:
        # Process operator with potential recursion
        if hasattr(op, '_etuplize_generator'):
            et_op_gen = op._etuplize_generator(return_bad_args=True)
            et_op = yield et_op_gen
        else:
            et_op = yield _etuplize_generator(op, return_bad_args=True)

        # Process arguments with potential recursion
        processed_args = []
        for a in args:
            if hasattr(a, '_etuplize_generator'):
                arg_gen = a._etuplize_generator(return_bad_args=True, convert_ConsPairs=False)
                processed_arg = yield arg_gen
            else:
                arg_gen = _etuplize_generator(a, return_bad_args=True, convert_ConsPairs=False)
                processed_arg = yield arg_gen
            processed_args.append(processed_arg)
        et_args = tuple(processed_args)

    res = etuple(et_op, *et_args, eval_obj=x)
    yield res


