import pyproj

def crs_to_json_dict(crs):
    '''Convert pyproj CRS to GeoJSON CRS dict format'''
    if crs is None:
        return None

    # Special case for WGS84 with lat/lon order -> use CRS84 (lon/lat order)
    crs_4326 = pyproj.CRS('EPSG:4326')
    crs84 = pyproj.CRS('urn:ogc:def:crs:OGC:1.3:CRS84')

    if crs == crs_4326:
        # EPSG:4326 has lat/lon order, but GeoJSON needs lon/lat
        return {
            'type': 'name',
            'properties': {
                'name': 'urn:ogc:def:crs:OGC:1.3:CRS84'
            }
        }
    elif crs == crs84:
        # Already in correct order
        return {
            'type': 'name',
            'properties': {
                'name': 'urn:ogc:def:crs:OGC:1.3:CRS84'
            }
        }
    else:
        # Regular CRS with authority
        auth = crs.to_authority()
        if auth:
            urn = f'urn:ogc:def:crs:{auth[0]}::{auth[1]}'
            return {
                'type': 'name',
                'properties': {
                    'name': urn
                }
            }

    return None

