def _crs_to_json_dict(crs):
    """
    Convert pyproj CRS to GeoJSON CRS dict format.

    Parameters
    ----------
    crs : pyproj.CRS or None
        Coordinate reference system to convert

    Returns
    -------
    dict or None
        GeoJSON CRS dictionary or None if crs is None
    """
    if crs is None:
        return None

    # Special case for WGS84 with lat/lon order -> use CRS84 (lon/lat order)
    # GeoJSON specification expects longitude/latitude order
    crs_4326 = CRS('EPSG:4326')
    crs84 = CRS('urn:ogc:def:crs:OGC:1.3:CRS84')

    if crs == crs_4326:
        # EPSG:4326 has lat/lon order, but GeoJSON needs lon/lat
        return {
            'type': 'name',
            'properties': {
                'name': 'urn:ogc:def:crs:OGC:1.3:CRS84'
            }
        }
    elif crs == crs84:
        # Already in correct order
        return {
            'type': 'name',
            'properties': {
                'name': 'urn:ogc:def:crs:OGC:1.3:CRS84'
            }
        }
    else:
        # Regular CRS with authority
        auth = crs.to_authority()
        if auth:
