    dest_path = self._prepare_dest_path(src_path, dest_path)
    if recursive and os.path.isdir(src_path):
        # For recursive directory copying, use copytree
        # Check if destination already exists and handle appropriately
        if os.path.exists(dest_path):
            if os.path.isdir(dest_path):
                # If destination is a directory, we want to copy the source directory INTO it
                # So the final path should be dest_path/src_basename
                final_dest = os.path.join(dest_path, os.path.basename(src_path))
                if os.path.exists(final_dest):
                    if os.path.isdir(final_dest):
                        shutil.rmtree(final_dest)
                    else:
                        os.remove(final_dest)
                shutil.copytree(src_path, final_dest)
            else:
                # Destination exists as a file, remove it first
                os.remove(dest_path)
                shutil.copytree(src_path, dest_path)
        else:
            # Destination doesn't exist, copytree will create it
            shutil.copytree(src_path, dest_path)
    else:
        # Original behavior for individual files or non-recursive mode
        shutil.copy(src_path, dest_path)
    if uid > -1 or gid > -1:
        # For recursive operations, apply chown recursively
        self.chown(dest_path, uid, gid, recursive=recursive)

