def is_tracked(self, path):
    try:
        return len(self.repo.git.ls_files(path)) != 0
    except Exception:
        # If git ls_files fails (e.g., for external paths), assume not tracked
        return False

def ignore(self, path):
    try:
        entry, gitignore = self._get_gitignore(path)
    except FileNotInRepoError:
        # External paths cannot be ignored by the local repository
        return

    ignore_list = []
    if os.path.exists(gitignore):
        ignore_list = open(gitignore, 'r').readlines()
        filtered = list(filter(lambda x: x.strip() == entry.strip(), ignore_list))
        if len(filtered) != 0:
            return

    content = entry
    if len(ignore_list) > 0:
        content = '\n' + content

    open(gitignore, 'a').write(content)

